79: export async function plan(objective, directory, {
80:   apiKey = process.env.OPENROUTER_API_KEY,
81:   fetchImpl = fetch,
82:   graphPath = join(directory, 'graph', 'graph.json'),
83: } = {}) {
84:   if (typeof objective !== 'string' || !objective.trim()) throw new Error('An objective is required.');
85:   if (!apiKey) throw new Error('Set OPENROUTER_API_KEY before planning.');
86:   const outcomes = await priorGraph(graphPath);
87:   const prior = outcomes?.length ? outcomes : null;
88:   const durable = relative(directory, graphPath);
89:   const investigate = await repositoryTools(directory, {
90:     exclude: [durable, durable.replace(/\.json$/, '.html')],
91:   });
92:   const output = join(directory, '.tag');
93:   try {
94:     await mkdir(output, { mode: 0o700 });
95:   } catch (error) {
96:     if (error.code === 'EEXIST') throw new Error('.tag already exists. Preserve or move it before starting another experiment.');
97:     throw error;
98:   }
99:   await writeFile(join(output, '.gitignore'), '*\n', { flag: 'wx', mode: 0o600 });
100:   // A failed run is an experimental result: keep what it did and what it answered.
101:   const attempt = { model: MODEL, createdAt: new Date().toISOString(), requests: 0, costUsd: 0, investigation: [] };
102:   let keep = false;
103:   try {
104:     const { data } = await request('/models', {}, fetchImpl);
105:     const model = data?.find(item => item.id === MODEL);
106:     const promptPrice = Number(model?.pricing?.prompt);
107:     const completionPrice = Number(model?.pricing?.completion);
108:     // Deliberately conservative caps, not a general-purpose cost reservation system.
109:     if (!model || !Number.isFinite(promptPrice) || promptPrice < 0 || promptPrice > 0.5 / 1e6
110:       || !Number.isFinite(completionPrice) || completionPrice < 0 || completionPrice > 1.5 / 1e6
111:       || Number(model.pricing.request ?? 0) !== 0) {
112:       throw new Error('Model unavailable or pricing exceeds the seed’s budget caps. Human review required.');
113:     }
114:     const messages = [
115:       { role: 'system', content: instructions },
116:       { role: 'user', content: objective },
117:     ];
118:     attempt.priorGraph = prior ? graphPath : null;
119:     let supplied = false;
120:     const investigation = attempt.investigation;
121:     const researched = () => investigation.some(item => item.tool === 'read_file' && /^\d+: /.test(item.result));
122:     for (let turn = 1; turn <= MAX_REQUESTS; turn++) {
123:       attempt.requests = turn;
124:       // Supplied with the graph up front, a real run answered with the graph: it restated three
125:       // of its four nodes verbatim, read nothing, and cited files it had never opened. The
126:       // durable state is real input, so it is withheld until the repository has actually been
127:       // investigated, and never allowed to stand in for investigating it.
128:       if (prior && !supplied && researched()) {
129:         supplied = true;
130:         messages.push({ role: 'user', content: `Work already performed on this objective, recorded by a human after observing what each attempt actually did:\n${prior.join('\n')}\nThis list is not a plan and is not exhaustive. Continue investigating if you have not finished. These outcomes are not repository evidence: do not cite them, or any path mentioned in them, unless you have read that file yourself in this investigation.` });
131:       }
132:       const body = {
133:         model: MODEL, messages, tools, max_tokens: MAX_OUTPUT,
134:         tool_choice: turn === MAX_REQUESTS ? 'none' : 'auto',
135:         temperature: 0.2,
136:         provider: { max_price: { prompt: 0.5, completion: 1.5 } },
137:       };
138:       if (Buffer.byteLength(JSON.stringify(body)) > MAX_CONTEXT_BYTES) {
139:         throw new Error('Research context limit reached. No graph saved; human review required.');
140:       }
141:       const response = await request('/chat/completions', {
142:         method: 'POST',
143:         headers: { Authorization: 'Bearer ' + apiKey, 'Content-Type': 'application/json' },
144:         body: JSON.stringify(body),
145:       }, fetchImpl);
146:       const cost = response.usage?.cost;
147:       attempt.costUsd = attempt.costUsd !== null && typeof cost === 'number' && Number.isFinite(cost) && cost >= 0
148:         ? attempt.costUsd + cost : null;
149:       const choice = response.choices?.[0];
150:       const message = choice?.message;
151:       if (!message || choice.finish_reason === 'length' || response.error) {
152:         throw new Error('The model returned an error or incomplete answer. No retry was made.');
153:       }
154:       if (message.tool_calls?.length) {
155:         if (turn === MAX_REQUESTS || message.tool_calls.length > 12) throw new Error('Investigation limit reached.');
156:         messages.push({ role: 'assistant', content: message.content ?? null, tool_calls: message.tool_calls });
157:         for (const call of message.tool_calls) {
158:           let args;
159:           let result;
160:           try {
161:             args = JSON.parse(call.function.arguments);
162:             result = await investigate(call.function.name, args);
163:           } catch {
164:             // Do not return raw filesystem errors or other environment details to the model.
165:             result = 'Tool unavailable or invalid arguments. Use listed tracked text files and the documented tool parameters.';
166:           }
167:           investigation.push({ tool: call.function.name, arguments: args ?? {}, result });
168:           messages.push({ role: 'tool', tool_call_id: call.id, content: result });
169:         }
170:         continue;
171:       }
172:       // Keep the answer before anything can reject it. A run that answered without investigating
173:       // at all was rejected here and its answer was lost, which is the failure failed-run.json
174:       // exists to prevent; the preservation path only triggered once this had already been set.
175:       attempt.answer = message.content;
176:       if (!researched()) {
177:         throw new Error('The model proposed a graph without reading repository evidence.');
178:       }
179:       // Seven of ten citations in one run named files the run never opened, one of them a file that
180:       // does not exist. Asking for honest citations has not worked, and repairing them would be
181:       // repair; a citation is checkable against the transcript, so it is checked.
182:       const opened = new Set(investigation
183:         .filter(item => item.tool === 'read_file' && /^\d+: /.test(item.result))
184:         .map(item => item.arguments.path));
185:       // A complete, otherwise valid graph was once discarded because the model wrapped it in a
186:       // markdown fence. Removing that envelope is not JSON repair: malformed JSON inside it,
187:       // a drifted objective or an invalid graph are still rejected exactly as before.
188:       const fenced = message.content.trim().match(/^```[a-z]*\s*\n([\s\S]*?)\n?```$/i);
189:       let graph;
190:       try {
191:         graph = validateGraph(JSON.parse(fenced ? fenced[1] : message.content), objective);
192:       } catch (error) {
193:         throw new Error(`Invalid planner graph: ${error.message}. No repair or retry was made.`);
194:       }
195:       const invented = graph.nodes.flatMap(node =>
196:         node.evidence.filter(item => !opened.has(cited(item))).map(item => `${node.id}: ${item}`));
197:       if (invented.length) {
198:         throw new Error(`The graph cites ${invented.length} file(s) this run never read:\n${invented.join('\n')}\nNo repair or retry was made.`);
199:       }
200:       graph.run = { model: MODEL, createdAt: attempt.createdAt, requests: turn, costUsd: attempt.costUsd, priorGraph: attempt.priorGraph, investigation };
201:       const html = renderGraph(graph);
202:       keep = true;
203:       await writeFile(join(output, 'graph.json'), JSON.stringify(graph, null, 2) + '\n', { flag: 'wx', mode: 0o600 });
204:       await writeFile(join(output, 'graph.html'), html, { flag: 'wx', mode: 0o600 });
205:       return join(output, 'graph.html');
206:     }
207:     throw new Error('Investigation limit reached. No graph saved.');
208:   } catch (error) {
209:     if (!attempt.investigation.length && attempt.answer === undefined) throw error;
210:     // Without this the run's transcript and rejected answer are lost and the failure cannot be diagnosed.
211:     const record = { objective, failure: error.message, run: attempt };
212:     try {
213:       await writeFile(join(output, 'failed-run.json'), JSON.stringify(record, null, 2) + '\n', { flag: 'wx', mode: 0o600 });
214:       keep = true;
215:       throw new Error(`${error.message} The attempt is preserved in .tag/failed-run.json; inspect and move it aside before running again.`);
216:     } catch (writeError) {
217:       throw writeError.message.includes(error.message) ? writeError : error;
218:     }
219:   } finally {
220:     if (!keep) await rm(output, { recursive: true });
221:   }
222: }
