3: // Two consecutive paid runs returned a valid graph that was thrown away because the model
4: // echoed the objective without its final full stop. An exact string match is a poor drift
5: // detector: blind to a graph that has genuinely wandered, and fatal to a punctuation mark.
6: // Surrounding whitespace and trailing sentence punctuation are ignored; nothing else is.
7: const sameObjective = (echoed, objective) => nonempty(echoed) && nonempty(objective)
8:   && echoed.trim().replace(/[.!?\s]+$/, '') === objective.trim().replace(/[.!?\s]+$/, '');
