4: // The smallest mechanism that lets a result of working a node reach the graph. The eighth
5: // dogfood run worked a node the graph itself proposed, refuted its hypothesis, and had
6: // nowhere to put that result: plan() writes graph.json once and nothing ever reads it back.
7: // This does not decide, schedule or execute anything. A human still chooses and does the work.
8: export async function record(graphPath, nodeId, outcome, { now = () => new Date().toISOString() } = {}) {
9:   if (!graphPath.endsWith('.json')) throw new Error('Point at a graph.json file.');
10:   if (typeof nodeId !== 'string' || !nodeId.trim()) throw new Error('A node id is required.');
11:   if (typeof outcome !== 'string' || !outcome.trim()) throw new Error('An outcome is required.');
12:   let graph;
13:   try {
14:     graph = JSON.parse(await readFile(graphPath, 'utf8'));
15:   } catch (error) {
16:     throw new Error(`Could not read a graph from ${graphPath}: ${error.message}`);
17:   }
18:   validateGraph(graph, graph?.objective);
19:   if (!graph.run?.createdAt) throw new Error('That graph has no run provenance; it was not produced by tag plan.');
20:   const node = graph.nodes.find(item => item.id === nodeId);
21:   if (!node) {
22:     throw new Error(`No node "${nodeId}" in ${graphPath}. It has: ${graph.nodes.map(item => item.id).join(', ')}.`);
23:   }
24:   graph.outcomes = [...(graph.outcomes ?? []),
25:     { node: node.id, title: node.title, at: now(), outcome: outcome.trim() }];
26:   validateGraph(graph, graph.objective);
27:   await writeFile(graphPath, JSON.stringify(graph, null, 2) + '\n');
28:   const htmlPath = graphPath.slice(0, -'.json'.length) + '.html';
29:   await writeFile(htmlPath, renderGraph(graph));
30:   return { htmlPath, outcomes: graph.outcomes.length };
31: }
